\label{ass:local_activity}
The nonnegative observable $Q$ is measurable and satisfies
$\int_0^H Q(\theta_s\omega)\,\mathrm{d} s<\infty$ almost surely for every finite $H$.

\label{def:bernstein}
A smooth function $\Phi: (0,\infty) \to [0,\infty)$ is called a \emph{Bernstein function} if $(-1)^{n-1}\Phi^{(n)}(\lambda) \ge 0$ for all $n \in \mathbb N$ and $\lambda > 0$. By the L\'evy--Khintchine representation, every Bernstein function with $\Phi(0+) = 0$ can be written as
\begin{equation}
 \Phi(\lambda) = b\,\lambda + \int_0^\infty \bigl(1 - e^{-\lambda r}\bigr)\,\nu(\mathrm{d} r),
 \label{eq:bernstein_rep}
\end{equation}
where $b \ge 0$ is the drift, and $\nu$ is a L\'evy measure on $(0,\infty)$ satisfying $\int_0^\infty (1 \wedge r)\,\nu(\mathrm{d} r) < \infty$.

\label{thm:clock_limit}
Under Assumptions~\ref{ass:local_activity} and~\ref{ass:level_C}, the activity measures converge vaguely to the measure of a strictly $\beta$-stable subordinator, and the cumulative operational clocks converge in the local $M_1$ topology (and hence in finite-dimensional distributions):
\begin{equation}\label{eq:regenerative_clock_limit}
 \mu^\varepsilon\Longrightarrow\mathrm{d} S^\beta
 \quad\text{in }\mathcal M([0,\infty)),\qquad
 A^\varepsilon
\Longrightarrow S^\beta
\quad\text{in }
\bigl(D([0,\infty)),M_1\bigr), \quad \text{as } \varepsilon\downarrow0,
\end{equation}
where the limiting process $S^\beta$ is the $\beta$-stable subordinator, with scale parameter $\kappa=\Gamma(1-\beta)/\mu_\tau$ determined by the environmental cycle characteristics.

\label{rem:burst_interpretation}
On the scale $T=\varepsilon^{-1}$, order $T$ regeneration cycles occur per unit macroscopic time, whereas only order one have integrated rewards comparable to $a_T$. These rare episodes produce the macroscopic activity atoms. Their physical durations vanish: writing $\ell_k=\tau_k-\tau_{k-1}$, finite mean duration gives, for every $\delta>0$,
\begin{equation}
 T\mathbb P(\ell_1>\delta T)
 \le\delta^{-1}\mathbb E[\ell_1\mathbf 1_{\{\ell_1>\delta T\}}]\longrightarrow0.
 \label{eq:cycle_duration_bound}
\end{equation}
A union bound therefore controls the maximal duration among order $T$ cycles. The heavy tail of the integrated reward determines the atom sizes, while the renewal rate $\mu_\tau^{-1}$ determines their frequency; see Figure~\ref{fig:regenerative_burst_clock}. Thus absolutely continuous microscopic activity concentrates into the atomic measure $\mathrm{d} S^\beta$, while the increasing clocks converge in Skorokhod $M_1$ topology.

\label{ass:slow_coefficients}
Let $b_i:\mathbb R^d\to\mathbb R^d$ and $\sigma_i:\mathbb R^d\to\mathbb R^{d\times d_i}$ for $i=0,1$.
We assume that the functions $b_0,b_1,\sigma_0,\sigma_1$ are globally bounded and globally Lipschitz. The two Brownian motions have dimensions $d_0,d_1$ and are mutually independent.

\label{thm:full_homogenization}
Under Assumptions~\ref{ass:slow_coefficients}, \ref{ass:local_activity}, \ref{ass:decoupling}, and~\ref{ass:level_C}, for every $x\in\mathbb R^d$, the process $\bar X^x$ defined above is a Markov process with Feller semigroup $\bar P$ and generator $\overline{\mathcal L}$. As $\varepsilon\downarrow0$:
\begin{enumerate}[label=(\roman*)]
\item Under the annealed law $\mathbb P\otimes\mathbb P_W$,
\begin{equation}\label{eq:main_fdd_limit}
 X^{\varepsilon,x}\xrightarrow{\mathrm{f.d.d.}}\bar X^x.
\end{equation}
\item For every $t\ge0$ and $f\in C_0(\mathbb R^d)$,
\begin{equation} \label{eq:main_operator_limits}
 \|P_t^\varepsilon f-\bar P_tf\|_\infty\longrightarrow0.
\end{equation}
\item The generator satisfies $C_c^\infty(\mathbb R^d)\subset D(\overline{\mathcal L})$ and, for every $f$ in this class,
\begin{equation}\label{eq:full_effective_gen}
 \overline{\mathcal L}f  =\mathcal L_0f-\kappa(-\mathcal L_1)^\beta f.
\end{equation}
\end{enumerate}

The operators $P_t^\varepsilon$ need not form a semigroup, so their Laplace-time integrals are not asserted to be resolvents; the limiting Laplace transform is the resolvent of $\overline{\mathcal L}$. Furthermore, \eqref{eq:main_operator_limits}
$\|P_t^\varepsilon f-\bar P_tf\|_{\infty}\le2\|f\|_{\infty}$ yield the Laplace-time convergence,
\begin{equation}
 \left\|\int_0^\infty e^{-\lambda t}P_t^\varepsilon f\,\mathrm{d} t
       -(\lambda I-\overline{\mathcal L})^{-1}f\right\|_{\infty}
 \le\int_0^\infty e^{-\lambda t}
          \|P_t^\varepsilon f-\bar P_tf\|_{\infty}\,\mathrm{d} t\longrightarrow0,
 \label{eq:proved_resolvent_convergence}
\end{equation}
for every $\lambda>0$ and $f\in C_0(\mathbb R^d)$.

\label{sec:topology}
The proof of Theorem~\ref{thm:full_homogenization} also gives extended-time functional convergence:
\begin{equation}
 (\tau^\varepsilon,Z^{\varepsilon,x})\Longrightarrow(\tau,Z^x)
 \quad\text{in }C_{\mathrm{loc}}([0,\infty);\mathbb R_+\times\mathbb R^d).
 \label{eq:main_extended_path_limit}
\end{equation}
However, this does not assert $J_1$ or $M_1$ convergence of the ordinary physical-time paths. To see this, consider the regenerative Brownian motion specialization $\mathcal L_0=0$, $\mathcal L_1=\tfrac12\Delta$, a burst with operational duration bounded away from zero occurs with probability bounded away from zero, while its physical duration vanishes. Conditional on such a burst, a Brownian coordinate has a fixed positive probability of making an internal excursion a fixed distance outside the segment joining two surrounding values, so the $M_1$ oscillation modulus remains nonzero on arbitrarily short physical-time intervals. This violates the $M_1$ tightness criterion \cite{Whitt2002} and consequently rules out both $M_1$ and $J_1$ convergence of the physical-time paths. This latter obstruction concerns the stated Brownian realization, not every activity semigroup. The nondecreasing clocks themselves do converge in $M_1$; their monotone-path criterion does not extend to the slow state. The parametrized limit retains the internal diffusion trajectory: on an interval $[t+S_{t-}^\beta,t+S_t^\beta]$ corresponding to a clock jump, $\tau$ is constant while $Z^x$ evolves through the activity diffusion. Thus \eqref{eq:main_extended_path_limit} is compatible with the physical-time $t$ obstruction.

\label{ass:uniform_ellipticity}
There exist constants $0<\lambda_*\le\Lambda_*<\infty$ such that
\begin{equation}
 \lambda_*|\xi|^2\le \xi^\top a_1(x)\xi\le\Lambda_*|\xi|^2,
 \qquad x,\xi\in\mathbb R^d.
 \label{eq:uniform_elliptic_activity}
\end{equation}

\label{cor:fractional_homog}
Under Assumptions~\ref{ass:slow_coefficients}, \ref{ass:local_activity}, \ref{ass:decoupling}, \ref{ass:level_C}, and~\ref{ass:uniform_ellipticity}, the microscopic diffusion homogenizes to a conservative Feller process with generalized $\alpha$-stable-like activity, where $\alpha=2\beta$. For every deterministic initial state, the convergence in Theorem~\ref{thm:full_homogenization}(i)--(ii) and the extended-time convergence \eqref{eq:main_extended_path_limit} hold. The effective generator is
\begin{equation}
 \overline{\mathcal L}f=\mathcal L_0f+\mathcal A_{\alpha}f
 =\mathcal L_0f-\kappa(-\mathcal L_1)^{\alpha/2}f,\qquad f\in\mathcal D.
 \label{eq:fractional_generator}
\end{equation}
The activity operator admits \eqref{eq:generalized_stable_spatial}, and its jump density satisfies, for constants $c,C>0$ independent of $x,y$,
\begin{equation}
 c|x-y|^{-d-\alpha}\le j_{\alpha}(x,y)
 \le C|x-y|^{-d-\alpha},\qquad 0<|x-y|\le1,
 \label{eq:local_stable_kernel_bounds}
\end{equation}
and $\sup_x\int_{\mathbb R^d\setminus\{x\}}(1\wedge|y-x|^2)j_{\alpha}(x,y)\,\mathrm{d} y<\infty$.

\label{rem:stable_brownian_specialization}
For $\mathcal L_1=\tfrac12\Delta$, the effective generator is $\mathcal L_0-\kappa2^{-\beta}(-\Delta)^\beta$. When $\mathcal L_0=0$, the limit is the symmetric $\alpha$-stable process $x+B_{S_t^\beta}$, with
\begin{equation}
 \overline{\mathcal L}=-\kappa\,2^{-\alpha/2}(-\Delta)^{\alpha/2},
 \qquad
 \mathbb E_0[e^{i\xi\cdot\bar X_t}]
 =\exp(-t\kappa2^{-\alpha/2}|\xi|^\alpha).
 \label{eq:fractional_laplacian}
\end{equation}
More generally, when $\mathcal L_0=0$, the limit is the activity diffusion at an independent stable clock; it need not be a symmetric stable L\'evy process.

