\label{thm:truncated_evolution}
Under Assumption~\ref{ass:slow_coefficients}, fix $\eta>0$, and let
$\Lambda_\eta$, $K_\eta$, and
$\mathcal P_{\mathbf T,\mathbf J}(t)$ be defined as above. Then the averaging 
\begin{equation}\label{eq:finite_burst_semigroup}
    \bar P_t^\eta f := \mathbb E\!\left[\mathcal P_{\mathbf T,\mathbf J}(t)f\right],
    \qquad f\in C_0(\mathbb R^d),
\end{equation}
defines a Feller semigroup on $C_0(\mathbb R^d)$ with conservative transition kernels. Its generator has domain $D(\mathcal L_\eta)=D(\mathcal L_0)$. Moreover, for $f\in D(\mathcal L_\eta)$, $\mathcal L_\eta$ is given by
\begin{equation}\label{eq:gen_eta}
    \mathcal L_\eta f = \mathcal L_0 f+\Lambda_\eta(K_\eta-I)f =\mathcal L_0 f
      +\int_{(\eta,\infty)}
        \bigl(P_r^{(1)}f-f\bigr)\,\nu(\mathrm{d} r).
\end{equation}

\label{prop:extended_stability}
Under Assumption~\ref{ass:slow_coefficients}, let $(\tau_n,c_n)$ and $(\tau,c)$ be deterministic extended clocks as in Lemma~\ref{prop:extended_clocks}, with $\tau_n\to\tau$ locally uniformly and $c_n(u)=u-\tau_n(u)$. In particular, Lemma~\ref{lem:inverse_clock_convergence} provides this convergence for $(\tau_n,c_n)=(\tau^{\varepsilon_n},c^{\varepsilon_n})$ whenever $A_t^{\varepsilon_n}\to S_t$ at every continuity point of $S$. Couple the solutions of \eqref{eq:extended_sde} using the same Brownian motions. Then, for every $U<\infty$,
\begin{equation}
 \sup_x\mathbb E\sup_{u\le U}|Z_u^{n,x}-Z_u^x|^2\longrightarrow0.
 \label{eq:extended_stability}
\end{equation}
The conclusion also holds for random clocks converging almost surely locally uniformly, when the entire family of clocks is independent of the Brownian motions.

\label{lem:physical_extended_representation}
Under Assumptions~\ref{ass:slow_coefficients}, \ref{ass:local_activity}, and~\ref{ass:decoupling}, the microscopic SDE has a unique nonexplosive strong solution, and $X_t^{\varepsilon,x} \overset{\mathrm{law}}{=} Z_{t+A_t^\varepsilon}^{\varepsilon,x}$, where $Z^{\varepsilon,x}$ solves \eqref{eq:extended_sde} with clocks $(\tau^\varepsilon,c^\varepsilon)$. 
Conditionally on the microscopic clock $\mathcal C^\varepsilon:=\sigma(A_t^\varepsilon:t\ge0)$, for every $T<\infty$,
\begin{equation}
    \operatorname{Law}\!\left( (X_t^{\varepsilon,x})_{0\le t\le T}\,\middle|\,\mathcal C^\varepsilon \right)
    =
    \operatorname{Law}\!\left( (Z_{t+A_t^\varepsilon}^{\varepsilon,x})_{0\le t\le T} \,\middle|\,\mathcal C^\varepsilon \right)
\end{equation}
as probability measures on $C([0,T];\mathbb R^d)$.
